using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class WorkDutyTests
{
    static readonly EntityId Lord=new("person:shingen"),Id=new("duty:one");
    static WorldSession Start()=>new(WorkProgressionTests.New());
    static void At(WorldSession s,long t)=>NewGameWorldTests.At(s,t);
    static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.True(s.Open(s.PlayerControl,m.Id,s.Revision).Code is ResultCode.Accepted or ResultCode.AlreadyAccepted);}
    static EntityId Work(WorldSession s){var i=NewGameWorld.LocalWork(s.DiagnosticSnapshot(),"request:work/"+s.Revision);Assert.Equal(ResultCode.Accepted,s.Submit(i,s.Revision).Code);At(s,s.Seconds+1);Open(s);At(s,s.Seconds+8);return s.DiagnosticSnapshot().Tasks.Last().Id;}
    static WorldSession Earn(){var s=Start();Work(s);Open(s);Assert.Equal(Lord,WorkDuty.Candidate(s.DiagnosticSnapshot()));return s;}
    static void Accept(WorldSession s)=>Assert.Equal(ResultCode.Accepted,s.AcceptWorkDuty(Id,Lord,s.PlayerControl,s.Revision).Code);
    [Fact]public void SealedRecognitionCannotUnlockDuty(){var s=Start();Work(s);Assert.Null(WorkDuty.Candidate(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.NotAvailable,s.AcceptWorkDuty(Id,Lord,s.PlayerControl,s.Revision).Code);}
    [Fact]public void EarnedRoleRequiresExplicitAcceptanceAndChangesNoPoliticalRights(){var s=Earn();var w=s.DiagnosticSnapshot();Assert.Null(WorkDuty.Active(w));Accept(s);var x=s.DiagnosticSnapshot();Assert.NotNull(WorkDuty.Active(x));Assert.Equal(ContractJson.Write(w.Offices),ContractJson.Write(x.Offices));Assert.Equal(ContractJson.Write(w.Grants),ContractJson.Write(x.Grants));Assert.Equal(1000,NewGameWork.Balance(x,s.PlayerControl));}
    [Fact]public void EarlierOrderNeverGainsRetroactiveFee(){var s=Earn();var before=s.DiagnosticSnapshot().Tasks.Last();Accept(s);Assert.Equal(0,NewGameWork.Reward(s.DiagnosticSnapshot(),before));}
    [Fact]public void NewDutyReallyPaysOnceAfterReportAndOpening(){var s=Earn();Accept(s);var t=Work(s);Assert.False(NewGameWork.CanRequest(s,t));Open(s);Assert.True(NewGameWork.CanRequest(s,t));Assert.Equal(ResultCode.Accepted,s.CollectWorkPayment(new("payment:duty"),t,s.PlayerControl,s.Revision).Code);var w=s.DiagnosticSnapshot();Assert.Equal(1020,NewGameWork.Balance(w,s.PlayerControl));Assert.Equal(980,NewGameWork.Balance(w,Lord));string h=ContractJson.CanonicalHash(w);Assert.Equal(ResultCode.AlreadyAccepted,s.CollectWorkPayment(new("payment:again"),t,s.PlayerControl,s.Revision).Code);Assert.Equal(h,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact]public void RetryAcceptanceDoesNotDuplicateDuty(){var s=Earn();Accept(s);Assert.Equal(ResultCode.AlreadyAccepted,s.AcceptWorkDuty(Id,Lord,s.PlayerControl,0).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.AcceptWorkDuty(Id,new("person:nobunaga"),s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.AcceptWorkDuty(new("duty:other"),Lord,s.PlayerControl,s.Revision).Code);Assert.Single(s.DiagnosticSnapshot().WorkCycle!.Duties!);}
    [Fact]public void CannotAcceptAnotherPersonsOrOldRevisionOffer(){var s=Earn();Assert.Equal(ResultCode.NotAvailable,s.AcceptWorkDuty(Id,Lord,Lord,s.Revision).Code);Assert.Equal(ResultCode.StateChanged,s.AcceptWorkDuty(Id,Lord,s.PlayerControl,s.Revision-1).Code);}
    [Fact]public void DutyIdsCannotBeReusedForCommands(){var s=Earn();Accept(s);var intent=NewGameWorld.LocalWork(s.DiagnosticSnapshot(),Id.Value);Assert.Equal(ResultCode.IdPayloadConflict,s.Submit(intent,s.Revision).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.DecideService(new(Id,CareerAction.Inquire,NewGameService.View(s.DiagnosticSnapshot()).Cases.Single().Case),s.PlayerControl,s.Revision).Code);}
    [Fact]public void RemoteAcceptanceIsRejected(){var s=Earn();Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:leave-town","suwa"),s.Revision).Code);At(s,s.Seconds+5);Assert.Equal(ResultCode.NotAvailable,s.AcceptWorkDuty(Id,Lord,s.PlayerControl,s.Revision).Code);}
    [Fact]public void ReleasedDutyEndsButEarnedDebtSurvives(){var s=Earn();Accept(s);var task=Work(s);Open(s);var c=NewGameService.View(s.DiagnosticSnapshot()).Cases.Single();Assert.Equal(ResultCode.Accepted,s.DecideService(new(new("request:release"),CareerAction.RequestRelease,c.Case),s.PlayerControl,s.Revision).Code);At(s,s.Seconds+2);Open(s);var w=s.DiagnosticSnapshot();Assert.Null(WorkDuty.Active(w));Assert.Equal(20,NewGameWork.Reward(w,w.Tasks.Single(t=>t.Id==task)));Assert.Equal(20,w.Debts.Single().Outstanding);Assert.Equal(ResultCode.Accepted,s.CollectWorkPayment(new("payment:after-release"),task,s.PlayerControl,s.Revision).Code);}
    [Fact]public void GenerationRestoreKeepsSameDutyAndNextPayment(){var s=Earn();Accept(s);s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"duty-"+Guid.NewGuid().ToString("N")),w.Definitions);store.Save(s,"manual",w.WorldId,new(0,1));var host=new WorldSessionHost(new(WorkProgressionTests.New()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("manual"),host.Current,host.Current.Revision));var restored=host.Current;Assert.Equal(ContractJson.CanonicalHash(w),ContractJson.CanonicalHash(restored.DiagnosticSnapshot()));var a=Work(s);var b=Work(restored);Open(s);Open(restored);Assert.Equal(a,b);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(restored.DiagnosticSnapshot()));}
    [Theory][InlineData("fee")][InlineData("principal")][InlineData("site")][InlineData("time")]
    public void ForgedAgreementRejected(string part){var s=Earn();Accept(s);var w=s.DiagnosticSnapshot();var a=w.WorkCycle!.Duties!.Single();w.WorkCycle=w.WorkCycle with{Duties=[part switch{"fee"=>a with{Fee=200},"principal"=>a with{Principal=new("person:nobunaga")},"site"=>a with{Site=new("site:suwa")},_=>a with{Revision=1,At=0}}]};Assert.ThrowsAny<Exception>(()=>ContractValidation.Validate(w));}
    [Fact]public void OldPolicyCannotAcquireDutyAndOldJsonHasNoNewField(){var w=WorkProgressionTests.New(false);Assert.Null(w.WorkCycle!.Duties);Assert.DoesNotContain("\"Duties\"",System.Text.Encoding.UTF8.GetString(ContractJson.Write(w)));var s=new WorldSession(ContractJson.Copy(w));Assert.Equal(ResultCode.NotAvailable,s.AcceptWorkDuty(Id,Lord,s.PlayerControl,s.Revision).Code);}
}
